CREATE TABLE projects (id TEXT PRIMARY KEY); CREATE TABLE sessions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), UNIQUE(id, project_id)); CREATE TABLE observations (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), session_id TEXT, scope TEXT NOT NULL CHECK(scope IN ('project','personal')), type TEXT NOT NULL, content TEXT NOT NULL, topic_key TEXT, producer TEXT NOT NULL, source_provider TEXT NOT NULL DEFAULT '', source_id TEXT NOT NULL DEFAULT '', state TEXT NOT NULL CHECK(state IN ('active','needs_review','archived')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, review_after INTEGER, FOREIGN KEY(session_id, project_id) REFERENCES sessions(id, project_id)); CREATE TRIGGER observations_boundary_insert BEFORE INSERT ON observations BEGIN INSERT OR IGNORE INTO projects(id) VALUES(NEW.project_id); INSERT OR IGNORE INTO sessions(id,project_id) SELECT NEW.session_id,NEW.project_id WHERE NEW.session_id IS NOT NULL; END; CREATE TRIGGER observations_boundary_update BEFORE UPDATE OF session_id ON observations BEGIN INSERT OR IGNORE INTO sessions(id,project_id) SELECT NEW.session_id,NEW.project_id WHERE NEW.session_id IS NOT NULL; END; CREATE UNIQUE INDEX observations_topic_key ON observations(topic_key) WHERE topic_key IS NOT NULL; CREATE TABLE observation_refs (observation_id TEXT NOT NULL REFERENCES observations(id) ON DELETE CASCADE, target_id TEXT NOT NULL REFERENCES observations(id), PRIMARY KEY(observation_id, target_id)); CREATE VIRTUAL TABLE observations_fts USING fts5(id UNINDEXED, content);
